31	export function parseCommandLine(argv, scriptPath) {
32	  const programName = getProgramName(scriptPath);
33	  let aValue;
34	  const unknown = [];
35	
36	  for (let index = 0; index < argv.length; index += 1) {
37	    const token = argv[index];
38	
39	    if (token === '-h' || token === '--help') {
40	      exitWithHelp(programName);
41	    }
42	
43	    if (token === '--a') {
44	      const next = argv[index + 1];
45	
46	      if (next === undefined || next.startsWith('-')) {
47	        exitWithParseError(programName, 'argument --a: expected one argument');
48	      }
49	
50	      aValue = next;
51	      index += 1;
52	      continue;
53	    }
54	
55	    if (token.startsWith('--a=')) {
56	      aValue = token.slice(4);
57	      continue;
58	    }
59	
60	    unknown.push(token);
61	  }
62	
63	  if (aValue === undefined) {
64	    exitWithParseError(programName, 'the following arguments are required: --a');
65	  }
66	
67	  if (unknown.length > 0) {
68	    exitWithParseError(programName, `unrecognized arguments: ${unknown.join(' ')}`);
69	  }
70	
71	  return { a: aValue };
72	}

 1	export function partition(values, predicate) {
 2	  const matches = [];
 3	  const nonMatches = [];
 4	
 5	  for (const value of values) {
 6	    if (predicate(value)) {
 7	      matches.push(value);
 8	    } else {
 9	      nonMatches.push(value);
10	    }
11	  }
12	
13	  return [matches, nonMatches];
14	}
