16	export function bucketize(values, keyFunction) {
17	  const buckets = new Map();
18	
19	  for (const value of values) {
20	    const key = keyFunction(value);
21	
22	    if (!buckets.has(key)) {
23	      buckets.set(key, []);
24	    }
25	
26	    buckets.get(key).push(value);
27	  }
28	
29	  return buckets;
30	}

