 8	function formatPythonString(value) {
 9	  return `'${value
10	    .replace(/\\/g, '\\\\')
11	    .replace(/'/g, "\\'")
12	    .replace(/\n/g, '\\n')
13	    .replace(/\r/g, '\\r')
14	    .replace(/\t/g, '\\t')}'`;
