21	export function parsePythonInt(rawPart) {
22	  const trimmed = rawPart.trim();
23	
24	  if (!/^[+-]?(?:\d+(?:_\d+)*)$/.test(trimmed)) {
25	    throw createValueError(rawPart);
26	  }
27	
28	  return BigInt(trimmed.replace(/_/g, ''));
29	}
