31	export function parseCommaSeparatedIntegers(rawValue) {
32	  return rawValue.split(',').map((part) => parsePythonInt(part));
33	}

 1	function formatPythonValue(value) {
 2	  if (typeof value === 'bigint') {
 3	    return value.toString();
 4	  }
 5	
 6	  if (typeof value === 'boolean') {
 7	    return value ? 'True' : 'False';
 8	  }
 9	
10	  if (Array.isArray(value)) {
11	    return `[${value.map((item) => formatPythonValue(item)).join(', ')}]`;
12	  }
13	
14	  if (value instanceof Map) {
15	    return formatPythonDict(value);
16	  }
17	
18	  return String(value);
19	}
