21	export function formatPythonTuple(items) {
22	  if (items.length === 1) {
23	    return `(${formatPythonValue(items[0])},)`;
24	  }
25	
26	  return `(${items.map((item) => formatPythonValue(item)).join(', ')})`;
27	}
