29	export function formatPythonDict(entries) {
30	  const parts = [];
31	
32	  for (const [key, value] of entries.entries()) {
33	    parts.push(`${formatPythonValue(key)}: ${formatPythonValue(value)}`);
34	  }
35	
36	  return `{${parts.join(', ')}}`;
37	}

